import type { Role } from '@prisma/client';

/**
 * Bodies for the two auth emails. Pure, so the copy is testable and the web
 * app never assembles HTML from user input: every value interpolated here is
 * generated by Scribe (URLs, hostnames, enum roles).
 */
export interface AuthEmailBody {
  subject: string;
  text: string;
  html: string;
}

function escapeHtml(value: string): string {
  return value
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

export function inviteEmail(input: { joinUrl: string; host: string; role: Role }): AuthEmailBody {
  const url = escapeHtml(input.joinUrl);
  return {
    subject: `You're invited to Scribe on ${input.host}`,
    text: [
      `You have been invited to Scribe (${input.host}) as ${input.role}.`,
      '',
      'Open this link to choose a password and sign in:',
      input.joinUrl,
      '',
      'The link is valid for 7 days and works once. If you were not expecting it, ignore this email.',
    ].join('\n'),
    html: [
      `<p>You have been invited to <strong>Scribe</strong> (${escapeHtml(input.host)}) as <strong>${input.role}</strong>.</p>`,
      `<p><a href="${url}">Choose a password and sign in</a></p>`,
      `<p style="color:#666;font-size:12px">The link is valid for 7 days and works once. If you were not expecting it, ignore this email.</p>`,
    ].join('\n'),
  };
}

export function passwordResetEmail(input: { resetUrl: string; host: string }): AuthEmailBody {
  const url = escapeHtml(input.resetUrl);
  return {
    subject: `Reset your Scribe password (${input.host})`,
    text: [
      `Someone asked to reset the password for this address on Scribe (${input.host}).`,
      '',
      'Open this link to set a new password:',
      input.resetUrl,
      '',
      'The link is valid for 1 hour and works once. If this was not you, ignore this email; your password is unchanged.',
    ].join('\n'),
    html: [
      `<p>Someone asked to reset the password for this address on <strong>Scribe</strong> (${escapeHtml(input.host)}).</p>`,
      `<p><a href="${url}">Set a new password</a></p>`,
      `<p style="color:#666;font-size:12px">The link is valid for 1 hour and works once. If this was not you, ignore this email; your password is unchanged.</p>`,
    ].join('\n'),
  };
}
